function detectScheduleConflicts(scheduledList) {
  // key: "date|time" -> count / list of IDs
  const timeCounts = {};
  scheduledList.forEach(item => {
    if (item.date !== '-' && item.time !== '-') {
      const key = `${item.date}__${item.time}`;
      if (!timeCounts[key]) timeCounts[key] = [];
      timeCounts[key].push(item.id);
    }
  });

  const conflictMap = {}; // id -> conflictingWith [ids]
  Object.entries(timeCounts).forEach(([key, ids]) => {
    if (ids.length > 1) {
      ids.forEach(id => {
        conflictMap[id] = ids.filter(otherId => otherId !== id);
      });
    }
  });

  return conflictMap;
}

function calculateSmartTimeWithSkip(baseTimeStr, intervalStr, occupiedTimesSet, existingMap, talentList) {
  let [hours, minutes] = baseTimeStr.split(':').map(Number);
  if (isNaN(hours)) hours = 9;
  if (isNaN(minutes)) minutes = 0;
  let interval = parseInt(intervalStr, 10);
  if (isNaN(interval)) interval = 40;

  const result = {};
  let currentMinutes = (hours * 60) + minutes;

  talentList.forEach(t => {
    // If talent is Rescheduled, they already own their slot
    if (t.status === 'Reschedule') {
      result[t.id] = t.time;
      return;
    }

    // If talent already has a locked time that does NOT conflict with a higher-priority Rescheduled candidate:
    if (existingMap && existingMap[t.id] && !occupiedTimesSet.has(existingMap[t.id])) {
      result[t.id] = existingMap[t.id];
      occupiedTimesSet.add(existingMap[t.id]);
      return;
    }

    // Find next available slot that is NOT in occupiedTimesSet
    while (true) {
      const h = Math.floor(currentMinutes / 60) % 24;
      const m = currentMinutes % 60;
      const timeStr = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ' WIB';

      if (!occupiedTimesSet.has(timeStr)) {
        result[t.id] = timeStr;
        occupiedTimesSet.add(timeStr);
        currentMinutes += interval;
        break;
      } else {
        // Skip occupied slot!
        currentMinutes += interval;
      }
    }
  });

  return result;
}

