    window.submitPostInterviewEvaluation = async function() {
      if (!currentPostInterviewTalentId) return;
      const talent = state.talents.find(t => t.id === currentPostInterviewTalentId || t.$id === currentPostInterviewTalentId);
      if (!talent) return;

      const feedback = (document.getElementById('postInterviewNotes') ? document.getElementById('postInterviewNotes').value : '').trim();
      const salary = (document.getElementById('postInterviewSalary') ? document.getElementById('postInterviewSalary').value : '').trim();
      const newStage = currentPostInterviewStage || 'Shortlisted';
      const newRating = currentPostInterviewRating || 4;

      const now = new Date();
      const timestamp = now.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' }) + ' ' + now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

      let updatedNotes = talent.notes || '';
      if (feedback) {
        const evalRemark = '\\n[Interview Result (' + newStage + ' - ' + timestamp + '): Rating ' + newRating + '/5 - ' + feedback + ']';
        updatedNotes = updatedNotes ? (updatedNotes + evalRemark) : evalRemark;
      }

      // Update in-memory talent
      talent.stage = newStage;
      talent.overallRating = newRating;
      if (salary) talent.expectedSalary = salary;
      talent.notes = updatedNotes;

      const packedNotes = packOutreachStatus(updatedNotes, talent.outreachStatus || 'Confirmed');

      closePostInterviewModal();
      renderFinalScheduleAgenda();
      renderBroadcastTable();
      renderBentoGrid();
      renderTableView();
      renderKanbanBoard();
      updateMetrics();

      showToast('✅ Hasil interview ' + talent.name + ' dipindahkan ke ' + newStage);

      // Save to Appwrite Cloud
      try {
        const docId = talent.$id || (talent.id || '').toLowerCase().replace(/[^a-z0-9_-]/g, '_');
        await databases.updateDocument(
          APPWRITE_CONFIG.databaseId,
